// Combine data from all three GitHub API calls
const commits = $input.all()[0]?.json?.body || [];
const issues = $input.all()[1]?.json?.body || [];
const pulls = $input.all()[2]?.json?.body || [];

const commitsArr = Array.isArray(commits) ? commits : [];
const issuesArr = Array.isArray(issues) ? issues.filter(i => i.pull_request === undefined) : [];
const pullsArr = Array.isArray(pulls) ? pulls.filter(p => p.merged_at !== null) : [];

// Build structured data for the Claude API
const repoInfo = {
  repo: $json.ghRepoUrl || 'https://github.com/n8n-io/n8n',
  period: {
    start: $now.minus(7, 'days').format('YYYY-MM-DD'),
    end: $now.format('YYYY-MM-DD'),
  },
  language: $json.language || 'EN',
};

const summary = {
  totalCommits: commitsArr.length,
  totalIssuesClosed: issuesArr.length,
  totalPRsMerged: pullsArr.length,
  topContributors: [...new Set(commitsArr.map(c => c.commit?.author?.name || c.author?.login).filter(Boolean))],
  recentCommits: commitsArr.slice(0, 10).map(c => ({
    message: c.commit?.message?.split('\n')[0] || '',
    author: c.commit?.author?.name || c.author?.login || 'Unknown',
    date: c.commit?.author?.date || '',
  })),
  closedIssues: issuesArr.slice(0, 10).map(i => ({
    title: i.title,
    number: i.number,
    author: i.user?.login,
    labels: i.labels?.map(l => l.name) || [],
  })),
  mergedPRs: pullsArr.slice(0, 10).map(p => ({
    title: p.title,
    number: p.number,
    author: p.user?.login,
    mergedBy: p.merged_by?.login,
  })),
};

// Build prompt for Claude
const languageSuffix = repoInfo.language === 'FR' 
  ? '\n\nIMPORTANT: Write the entire summary in French.'
  : '\n\nIMPORTANT: Write the entire summary in English.';

const prompt = `You are a technical writer creating a weekly development summary.

Here is the repo activity for the week of ${repoInfo.period.start} to ${repoInfo.period.end}:

**Commits**: ${summary.totalCommits} commits total
**Issues Closed**: ${summary.totalIssuesClosed}
**PRs Merged**: ${summary.totalPRsMerged}
**Top Contributors**: ${summary.topContributors.join(', ') || 'N/A'}

Key commits this week:
${summary.recentCommits.map(c => `- ${c.message} (${c.author}, ${c.date?.slice(0, 10)})`).join('\n')}

Issues closed:
${summary.closedIssues.map(i => `- #${i.number}: ${i.title}`).join('\n')}

Merged PRs:
${summary.mergedPRs.map(p => `- #${p.number}: ${p.title} by ${p.author || p.mergedBy || 'Unknown'}`).join('\n')}

Write a narrative weekly summary (3-5 paragraphs) highlighting:
1. What was accomplished this week (big picture)
2. Notable changes or breaking updates
3. Community contributions worth mentioning
4. What to expect next week (if inferrable from recent commits)

Style: professional but engaging. Use markdown.${languageSuffix}`;

return [{
  json: {
    prompt,
    summary,
    repoInfo,
    slackWebhook: $json.slackWebhook || '',
    discordWebhook: $json.discordWebhook || '',
    emailTo: $json.emailTo || '',
    deliveryMethod: $json.deliveryMethod || 'slack',
  }
}];

// Extract Claude's response
const claudeResponse = $input.first().json;
const content = claudeResponse.content?.[0]?.text || claudeResponse.body?.content?.[0]?.text || JSON.stringify(claudeResponse);
const repoInfo = $input.first().json.repoInfo || {};

return [{
  json: {
    summary: content,
    repo: repoInfo.repo || 'N/A',
    period: repoInfo.period || {},
    slackWebhook: $json.slackWebhook || '',
    discordWebhook: $json.discordWebhook || '',
    emailTo: $json.emailTo || '',
    deliveryMethod: $json.deliveryMethod || 'slack',
  }
}];

// Route by delivery method
const method = ($json.deliveryMethod || 'slack').toLowerCase();

if (method === 'slack' && $json.slackWebhook) {
  return [{json: $json, ...$json}];
} else if (method === 'discord' && $json.discordWebhook) {
  // Returning to second output
  return [null, {json: $json, ...$json}];
} else if (method === 'email' && $json.emailTo) {
  return [null, null, {json: $json, ...$json}];
} else {
  // Fallback to Slack
  return [{json: $json, ...$json}];
}

// Log success and return the summary
const method = ($json.deliveryMethod || 'slack').toUpperCase();
const repoUrl = $json.repo || '';
const repoName = repoUrl.split('/').slice(-2).join('/');
const period = $json.period || {};

return [{
  json: {
    success: true,
    deliveredVia: method,
    repo: repoName,
    period: `${period.start || '?'} to ${period.end || '?'}`,
    summaryPreview: ($json.summary || '').slice(0, 200) + '...',
    timestamp: new Date().toISOString(),
  }
}];
